#' Helper function to compare parameter summaries from TMB and JSON sources.
#'
#' @description This function reads a saved FIMS model fit object, processes its TMB and JSON components to extract parameter names and labels, and then compares them for consistency. It also checks for duplicate parameter IDs in the JSON output.
#' @param model_fit_path A character string specifying the path to the .RDS file
#'   containing the model fit object.
#' @return Invisible `NULL` if tests pass. Throws an error via `cli::cli_abort`
#'   if the checks fail.
compare_tmb_and_json_outputs <- function(model_fit_path) {
  # Load the model fit object from the provided path.
  fit <- readRDS(model_fit_path)
  # Extract the core TMB components (object, sdreport, optimization result)
  # from the fit object.
  obj <- get_obj(fit)
  sdreport <- get_sdreport(fit)
  opt <- get_opt(fit)
  parameter_names <- get_obj(fit)[["par"]] |>
    names()

  # Reshape the TMB output into a standardized data frame.
  # This serves as the "expected" result to compare against.
  tmb_output <- FIMS:::reshape_tmb_estimates(
    obj = obj,
    sdreport = sdreport,
    opt = opt,
    parameter_names = parameter_names
  ) |>
    # Select only the columns needed for the comparison to ensure a clean test.
    dplyr::select(
      module_name, label
    ) |>
    # Remove any duplicate rows.
    dplyr::distinct() |>
    # TODO: The test fails for fit objects from estimation runs because the TMB
    # output includes the label "log_r," which is not present in the JSON output.
    # For now, manually remove `log_r` here and create a new issue to track this.
    dplyr::filter(label != "log_r") |>
    # TODO: Allow for comparison of random effects
    dplyr::filter(label != "re")

  # Extract the model_output, which contains the JSON-like structure.
  model_output <- get_model_output(fit)
  # Reshape the output from the JSON structure into a data frame.
  json_output <- FIMS:::reshape_json_estimates(model_output)

  # Check for any duplicated parameter_id entries in the JSON output, which
  # would indicate a problem in the reshaping logic.
  # Use a tryCatch block to provide a more informative error message if the
  # comparison using testthat::expect_equal fails.
  duplicated_parameter_ids <- json_output |>
    dplyr::count(parameter_id) |>
    # TODO: check if we need to exclude -999
    dplyr::filter(n > 1 & !is.na(parameter_id))

  tryCatch(
    {
      #' @description Test that `reshape_json_estimates()` does not produce duplicated `parameter_id`s.
      expect_equal(nrow(duplicated_parameter_ids), 0)
    },
    error = function(e) {
      cli::cli_abort(
        c(
          "x" = "There are duplicated `parameter_id`s in the JSON output!",
          "i" = "The duplicated `parameter_id`s are: {.val {duplicated_parameter_ids[['parameter_id']]}}",
          "i" = "The data been used is: {.val {model_fit_path}}",
          "!" = "Original error: {.emph {e$message}}"
        ),
        .call = NULL
      )
    }
  )

  # Compare the structure of the JSON output against the TMB output.
  # Prepare the JSON summary for comparison by selecting, filtering, and sorting
  # it in the same way as the TMB summary.
  json_output <- json_output |>
    dplyr::select(module_name, label) |>
    dplyr::distinct()

  # Find module names that are present in TMB output but missing in JSON output.
  # anti_join() returns rows in the first data frame that do not have a match
  # in the second data frame based on the specified column.
  missing_module_name_in_json <- dplyr::anti_join(
    tmb_output |>
      # remove log_sd b/c this is a column in the json_output rather than a
      # label with an entire row as it is in the tmb_output
      dplyr::filter(label != "log_sd") |>
      dplyr::filter(!is.na(module_name)) |>
      dplyr::select(module_name),
    json_output |>
      dplyr::select(module_name)
  )


  # Find labels that are present in TMB output but missing in JSON output.
  missing_label_in_json <- dplyr::anti_join(
    tmb_output |>
      # remove log_sd b/c this is a column in the json_output rather than a
      # label with an entire row as it is in the tmb_output
      dplyr::filter(label != "log_sd") |>
      dplyr::select(label),
    json_output |>
      dplyr::select(label)
  )

  # Wrapping the test in tryCatch() allows us to provide
  # a more user-friendly and informative error message.
  tryCatch(
    {
      #' @description Test that all `module_name` values in the TMB output are found in the JSON output for a given model fit.
      expect_equal(nrow(missing_module_name_in_json), 0)
    },
    error = function(e) {
      cli::cli_abort(
        c(
          "x" = "`module_name` from TMB output is missing in the JSON output!",
          "i" = "Missing `module_name`s: {.val {missing_module_name_in_json}}",
          "i" = "Model fit object: {.val {model_fit_path}}",
          "!" = "Original error: {.emph {e$message}}"
        ),
        .call = NULL
      )
    }
  )

  tryCatch(
    {
      #' @description Test that all `label` values in the TMB output are found in the JSON output for a given model fit.
      expect_equal(nrow(missing_label_in_json), 0)
    },
    error = function(e) {
      cli::cli_abort(
        c(
          "x" = "`label` from TMB output is missing in the JSON output!",
          "i" = "Missing `label`s: {.val {missing_label_in_json}}",
          "i" = "Model fit object: {.val {model_fit_path}}",
          "!" = "Original error: {.emph {e$message}}"
        ),
        .call = NULL
      )
    }
  )
}

## IO correctness ----
test_that("`reshape_json_estimates()` output matches TMB for a deterministic run", {
  # Define the path to the deterministic model run fixture.
  deterministic_path <- testthat::test_path(
    "fixtures",
    "deterministic_age_length_comp.RDS"
  )

  #' @description Test that `reshape_json_estimates()` produces output matching TMB.
  compare_tmb_and_json_outputs(deterministic_path)
})

test_that("`reshape_json_estimates()` output matches TMB for an estimation run", {
  # Load the test data from an RDS file containing model fits.
  # List all RDS files in the fixtures directory that match the pattern "fit_*.RDS"
  fit_files <- list.files(
    path = testthat::test_path("fixtures"),
    pattern = "^fit.*\\.RDS$",
    full.names = TRUE
  )

  #' @description Test that `reshape_json_estimates()` produces output matching TMB.
  result <- purrr::map(fit_files, compare_tmb_and_json_outputs)
})

test_that("`reshape_json_estimates()` reports the ages and lengths from the data", {
  # Shift the ages and scale the length bins so the values differ from their
  # positions, i.e., the first age is 3 and the second length bin is 500
  shifted_data <- data_big |>
    dplyr::mutate(age = .data$age + 2, length = .data$length * 10)
  data_4_model <- FIMSFrame(shifted_data)
  fit <- setup_default_parameters(data = data_4_model) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        .data$estimation_type == "random_effects",
        "fixed_effects",
        .data$estimation_type
      )
    ) |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = FALSE)
  estimates <- FIMS:::reshape_json_estimates(get_model_output(fit))
  clear()
  ages <- 3:14
  lengths <- seq(0, 11000, by = 500)
  length_rows <- dplyr::filter(estimates, !is.na(.data$length))
  log_rzero <- dplyr::filter(estimates, .data$label == "log_rzero")

  #' @description Test that `reshape_json_estimates()` gives the initial numbers at age the ages from the data, in order.
  expect_equal(
    object = dplyr::filter(estimates, .data$label == "log_init_naa")[["age"]],
    expected = ages
  )
  #' @description Test that `reshape_json_estimates()` only reports ages from the data.
  expect_true(all(stats::na.omit(estimates[["age"]]) %in% ages))
  #' @description Test that `reshape_json_estimates()` gives each fleet the length bins from the data.
  expect_equal(
    object = purrr::map(
      split(length_rows[["length"]], length_rows[["fleet"]]),
      \(x) sort(unique(x))
    ),
    expected = list(fleet1 = lengths, survey1 = lengths)
  )
  #' @description Test that `reshape_json_estimates()` leaves age and length missing for a parameter without either dimension.
  expect_true(all(is.na(c(log_rzero[["age"]], log_rzero[["length"]]))))
  #' @description Test that `reshape_json_estimates()` replaces the age_i and length_i positions with age and length.
  expect_false(any(c("age_i", "length_i") %in% names(estimates)))
})

## Edge handling ----
test_that("`reshape_json_estimates()` links selectivity to fleets by id", {
  data_4_model <- FIMSFrame(data_big)
  # Fixed-effect recruitment deviations avoid the random-effect density join,
  # which matches rows by value and the default deviations are all zero
  fit <- setup_default_parameters(data = data_4_model) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        .data$estimation_type == "random_effects",
        "fixed_effects",
        .data$estimation_type
      )
    ) |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = FALSE)
  model_output <- get_model_output(fit)
  clear()
  selectivity_fleets <- function(json) {
    FIMS:::reshape_json_estimates(json) |>
      dplyr::filter(.data$module_name == "Selectivity") |>
      dplyr::distinct(.data$module_id, .data$fleet) |>
      dplyr::arrange(.data$module_id) |>
      dplyr::pull(.data$fleet)
  }
  # fleet1 uses selectivity 1 and survey1 uses selectivity 2, in the same order
  # as the fleets, so swap the ids to check the link follows selectivity_id
  swapped_output <- model_output |>
    gsub(
      pattern = '"selectivity_id": 1,',
      replacement = '"selectivity_id": 0,',
      fixed = TRUE
    ) |>
    gsub(
      pattern = '"selectivity_id": 2,',
      replacement = '"selectivity_id": 1,',
      fixed = TRUE
    ) |>
    gsub(
      pattern = '"selectivity_id": 0,',
      replacement = '"selectivity_id": 2,',
      fixed = TRUE
    )
  #' @description Test that `reshape_json_estimates()` names the fleet of each selectivity module from the fleet's selectivity id, not the fleet order.
  expect_equal(
    object = selectivity_fleets(swapped_output),
    expected = c("survey1", "fleet1")
  )
  shared_output <- gsub(
    pattern = '"selectivity_id": 2,',
    replacement = '"selectivity_id": 1,',
    x = model_output,
    fixed = TRUE
  )
  #' @description Test that `reshape_json_estimates()` leaves the fleet missing for a selectivity module used by more than one fleet.
  expect_equal(
    object = selectivity_fleets(shared_output),
    expected = c(NA_character_, NA_character_)
  )
})

test_that("`reshape_json_estimates()` reads output saved without ages and lengths", {
  data_4_model <- FIMSFrame(data_big)
  fit <- setup_default_parameters(data = data_4_model) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        .data$estimation_type == "random_effects",
        "fixed_effects",
        .data$estimation_type
      )
    ) |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = FALSE)
  model_output <- get_model_output(fit)
  clear()
  estimates <- FIMS:::reshape_json_estimates(model_output)
  # Output from before the ages and lengths were written
  older_output <- gsub(
    pattern = '"(ages|lengths)": \\[[^]]*\\],',
    replacement = "",
    x = model_output
  )
  older_estimates <- FIMS:::reshape_json_estimates(older_output)

  #' @description Test that `reshape_json_estimates()` leaves age missing for output without ages.
  expect_true(all(is.na(older_estimates[["age"]])))
  #' @description Test that `reshape_json_estimates()` leaves length missing for output without lengths.
  expect_true(all(is.na(older_estimates[["length"]])))
  #' @description Test that `reshape_json_estimates()` returns the same rows and other columns with or without ages and lengths.
  expect_equal(
    object = dplyr::select(older_estimates, -dplyr::all_of(c("age", "length"))),
    expected = dplyr::select(estimates, -dplyr::all_of(c("age", "length")))
  )
})


